//アイテムが編集状態であるかつ選択行が一行のみのときボタンを活性化させる
// 編集モードに基づく無効化フラグ指定
const isEditMode = this.isEditMode;

// 単一行選択判定
// const singleSelection = options.getState().grid.selectedRows.length == '1';
const singleSelection = this.grid.getSelectedItemIds().length== '1';

// 有効化判定
const isEnabled = isEditMode && singleSelection;
const result = {disabled: !isEnabled};

return result;
